'use strict';

// MODULES //

var sincos = require( '@stdlib/math-base-special-sincos' ).assign;
var exp = require( '@stdlib/math-base-special-exp' );


// VARIABLES //

// Pre-allocate workspace array:
var WORKSPACE = [ 0.0, 0.0 ];


// MAIN //

/**
* Evaluates the cis function for a double-precision complex floating-point number and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* var Float64Array = require( '@stdlib/array-float64' );
*
* var out = assign( 0.0, 0.0, new Float64Array( 2 ), 1, 0 );
* // returns <Float64Array>[ 1.0, 0.0 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	var e;

	sincos( re, WORKSPACE, 1, 0 );
	if ( im === 0.0 ) {
		out[ offsetOut ] = WORKSPACE[ 1 ];
		out[ offsetOut+strideOut ] = WORKSPACE[ 0 ];
		return out;
	}
	e = exp( -im );
	out[ offsetOut ] = WORKSPACE[ 1 ] * e;
	out[ offsetOut+strideOut ] = WORKSPACE[ 0 ] * e;
	return out;
}


// EXPORTS //

module.exports = assign;
